// Regenerates www/error.html from error.template.html + www/offline.js +
// www/offline.css, inlining both assets. See the comment in the template for
// why inlining is mandatory. Run before `npx cap copy android`.
//
//   node build-error-page.mjs            write www/error.html
//   node build-error-page.mjs --check    exit 1 if it is out of date
//
// error.html is tracked, so that a fresh clone can `cap sync` without having
// run this first. --check is what keeps a tracked, generated file honest: the
// tests run it, so editing a source and forgetting to regenerate fails there
// rather than shipping a page that no longer matches its sources.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
// Line endings normalised on the way in: git may check the sources out with
// CRLF on Windows, and a comparison that tripped over that would report
// every page as stale.
const read = p => readFileSync(join(here, p), "utf8").replace(/\r\n/g, "\n");

const js = read("www/offline.js");
if (js.includes("</script>"))
  throw new Error("offline.js contains '</script>' — cannot be inlined");

const banner = "<!-- GENERATED by build-error-page.mjs — edit " +
  "error.template.html / offline.js / offline.css instead. -->\n";
// Function replacements so '$' sequences in the assets stay literal.
const out = banner + read("error.template.html")
  .replace("@@CSS@@", () => read("www/offline.css").trim())
  .replace("@@JS@@", () => js.trim());

if (process.argv.includes("--check")) {
  let current = "";
  try { current = read("www/error.html"); } catch (e) { /* absent = stale */ }
  if (current !== out) {
    console.error("www/error.html is out of date — run: node build-error-page.mjs");
    process.exit(1);
  }
  console.log("www/error.html is up to date");
} else {
  writeFileSync(join(here, "www/error.html"), out);
  console.log("www/error.html regenerated");
}
